import Log from './Log';
import LogOutputs from './LogOutputs';
import * as types from './types';
import {ConsoleHandler, SyslogHandler, FileHandler} from './output-handlers';
import Singletons from './Singletons';
import './deprecation';
import defaultConfig from './defaultConfig';

const LogBase:typeof Log = Singletons.enforceSingleton<Log>(Log) as typeof Log;

export {
    LogBase,
    Log,
    LogOutputs,
    types,
    ConsoleHandler,
    SyslogHandler,
    FileHandler
};

Log.loadConfig(defaultConfig);

//Hack so we can export the Type as well as the Value of Log
export default class LogSingleton extends LogBase {}
