import LogOutputs from './LogOutputs';
import {Level, LoggingConfig, Output, OutputsConfig} from './types';
import {levelOrder} from './types/Level';
import {enumerate} from './utils';
import {
    default as outputHandlers,
    ConsoleHandler,
    SyslogHandler,
    FileHandler
} from './output-handlers';

const NAMESPACE_DELIMITER: string = '/';

/**
 * Map of logging configurations for each namespace.
 * The namespace configs are stored flat, e.g. 'parent' and 'parent/child'
 * @interface OutputPerNamespace
 */
interface OutputPerNamespace {

    /**
     * The namespace to map to {LevelPerOutput}. Specify one of these for each
     * namespace you'd like to configure.
     * @name OutputPerNamespace#namespace
     * @type {LevelPerOutput}
     */
    [namespace: string]: LevelPerOutput;
}

/**
 * Map of output level for each output channel.
 * OutputPerNamespace maps namespaces to these.
 * @interface LevelPerOutput
 */
interface LevelPerOutput {

    /**
     * The output to map to the {Level}. Specify one of these for each output
     * channel you'd like to configure.
     * @name LevelPerOutput#output
     * @type {Level}
     */
    [output: string]: Level;
}

/**
 * Log class - centralized logging facility
 * @class Log
 * @param {string} [namespace=''] The namespace to log to
 * @param {Log} [parent] The log parent (prepended to the namespace)
 */
 class Log {

     /**
      * Current version of the library.
      * @name Log.version
      * @type {string}
      */
     public static version:string = '2.6.3';

    /**
     * The global logger, with empty namespace
     */
    static readonly global: Log = new Log();

    // Global logging configuration, usually loaded from JSON
    // Holds the minimum logging levels per output, per namespace
    private static _outputPerNamespace: OutputPerNamespace;

    // A list of the output levels, for enumerating
    private static _outputs = enumerate<Output>(Output);

    // The handlers for each output channel, referenced by their name
    private static _outputHandlers = outputHandlers;

    // Whether or not to log globally uncaught exceptions
    private static _logUncaughtExceptions: boolean;

    // Whether or not to log globally unhandled promise rejections
    private static _logUnhandledRejections: boolean;

    /**
     * The namespace of this logger instance
     * @name Log#namespace
     * @type {string}
     */
    readonly namespace: string;

    /**
     * The level of each output channel of the global logger
     * @name Log.outputs
     * @type {LogOutputs}
     */
    public static get outputs(): LogOutputs {
        return Log.global.outputs;
    }

    /**
     * Set the logging configuration from input (e.g. parsed from JSON file)
     * @method Log.loadConfig
     * @param {LoggingConfig} loggingConfig The configuration to load
     */
    public static loadConfig(loggingConfig: LoggingConfig): void {
        Log.logUncaughtExceptions = loggingConfig.logUncaughtExceptions;
        Log.logUnhandledRejections = loggingConfig.logUnhandledRejections;
        const outputsIn = loggingConfig.outputs;
        for(let output in outputsIn) {
            this._outputHandlers[output].config = outputsIn[output];
        }
        const outputPerNamespace: OutputPerNamespace =
            Log._outputPerNamespace = {};
        const outputPerNamespaceIn: OutputPerNamespace =
            loggingConfig.namespaces;
        for(let namespace in outputPerNamespaceIn) {
            const levelPerOutput: LevelPerOutput =
                outputPerNamespace[namespace] = {};
            const levelPerOutputIn = outputPerNamespaceIn[namespace];
            for(let output in levelPerOutputIn) {
                const levelIn = levelPerOutputIn[output];
                const level: Level = <Level>levelIn;
                levelPerOutput[output] = level;
            }
        }
    }

    /**
     * Generate LoggingConfig for output (e.g. to stringify to JSON file)
     * @method Log.getConfig
     * @return {LoggingConfig}
     */
    public static getConfig(): LoggingConfig {
        const logUncaughtExceptions = Log.logUncaughtExceptions;
        const logUnhandledRejections = Log.logUnhandledRejections;
        const outputs: OutputsConfig = {
            console: (<ConsoleHandler>this._outputHandlers.console).config,
            syslog: (<SyslogHandler>this._outputHandlers.syslog).config,
            file: (<FileHandler>this._outputHandlers.file).config
        };
        const namespaces: OutputPerNamespace = {};
        for(let namespace in Log._outputPerNamespace) {
            namespaces[namespace] = Log._outputPerNamespace[namespace];
        }
        return {
            logUncaughtExceptions,
            logUnhandledRejections,
            outputs,
            namespaces
        };
    }

    // Chop off the last part of the namespace, including its delimiter
    private static _parentNamespace(namespace: string): string {
        const lastSlash: number = namespace.lastIndexOf(NAMESPACE_DELIMITER);
        return lastSlash > -1
            ? namespace.slice(0, lastSlash)
            : '';
    }

    // Log uncaught exceptions everywhere except the console, and re-throw
    // the error so that the console will log it as usual
    private static _uncaughtExceptionLogger(error: string|Error) {
        Log.global._writeAllNoConsole(Level.error, error);
        throw error;
    }

    /**
     * Whether or not to log globally uncaught exceptions
     * @name Log.logUncaughtExceptions
     * @type {boolean}
     */
    public static set logUncaughtExceptions(log: boolean) {
        if(log && !Log._logUncaughtExceptions) {
            process.on('uncaughtException', Log._uncaughtExceptionLogger);
        }
        else if(!log && Log._logUncaughtExceptions) {
            process.removeListener(
                'uncaughtException',
                Log._uncaughtExceptionLogger
            );
        }
        Log._logUncaughtExceptions = log;
    }

    public static get logUncaughtExceptions(): boolean {
        return Log._logUncaughtExceptions;
    }

    // Log unhandled promise rejections everywhere except the console, and
    // re-throw the error so that the console will log it as usual
    private static _unhandledRejectionLogger(error: string|Error) {
        Log.global._writeAllNoConsole(Level.error, error);
    }

    // In electron, unhandledrejection event is on window, not process, and
    // the callback signature is different
    private static _unhandledRejectionWindowLogger(event: any) {
        Log._unhandledRejectionLogger(event.reason);
    }

    /**
     * Whether or not to log globally unhandled promise rejections
     * @name Log.logUnhandledRejections
     * @type {boolean}
     */
    public static set logUnhandledRejections(log: boolean) {
        if(log && !Log._logUnhandledRejections) {
            if(typeof window !== 'undefined') {
                window.addEventListener(
                    'unhandledrejection',
                    Log._unhandledRejectionWindowLogger
                );
            }
            else {
                process.on('unhandledRejection', Log._unhandledRejectionLogger);
            }
        }
        else if(!log && Log._logUnhandledRejections) {
            if(typeof window !== 'undefined') {
                window.removeEventListener(
                    'unhandledrejection',
                    Log._unhandledRejectionWindowLogger
                );
            }
            else {
                process.removeListener(
                    'unhandledRejection',
                    Log._unhandledRejectionLogger
                );
            }
        }
        Log._logUnhandledRejections = log;
    }

    public static get logUnhandledRejections(): boolean {
        return Log._logUnhandledRejections;
    }

    // Check to see if the first level is greater than or equal to the second.
    private static _levelGreaterOrEqual(
        levelOne: Level,
        levelTwo: Level
    ): boolean {
        return levelOrder.indexOf(levelOne) >= levelOrder.indexOf(levelTwo);
    }

    constructor(namespace: string = '', parent?: Log) {
        this.namespace =
            parent
                ? parent.namespace + NAMESPACE_DELIMITER + namespace
                : namespace;
    }

    /**
     * A reference to the top level logger instance with namespace ''
     * @name Log#global
     * @type {Log}
     */
    public get global(): Log { return Log.global; }

    /**
     * Configuration for the output of this logger
     * @name Log#outputs
     * @type {LogOutputs}
     */
    public get outputs(): LogOutputs {
        let namespace: string = this.namespace;
        while(!Log._outputPerNamespace[namespace]) {
            namespace = Log._parentNamespace(namespace);
        }
        return new LogOutputs(new Log(namespace), this.namespace);
    }

    /**
     * Creates a new Log instance with namespace `this.namespace + '/' + subNamespace`
     * @method Log#createChild
     * @param {string} subNamespace New namespace which will be appended to the parent namespace
     * @return {Log}
     */
    public createChild(subNamespace: string): Log {
        return new Log(subNamespace, this);
    }

    /**
     * Set the minimum logging level for a given output for this namespace
     * This is generally not invoked directly, but by LogOutputs by setting
     * one of the properties of the outputs property of a log instance
     * e.g. `log.outputs.console = 'debug';`
     * @method Log#setLevelForOutput
     * @param {Output} output The output for which to set the level
     * @param {Level} level The level to which to set the output
     */
    public setLevelForOutput(output: Output, level: Level) {
        let namespaceConfig: LevelPerOutput =
            Log._outputPerNamespace[this.namespace];
        if(!namespaceConfig) {
            namespaceConfig = Log._outputPerNamespace[this.namespace] = {};
        }
        namespaceConfig[output.toString()] = level;
    }

    /**
     * Check minimum logging level for each output channel for this log's
     * namespace, and log the message if this level is debug or lower
     * @method Log#debug
     * @param {any[]} ...args The arguments to log
     * @return {Log} Instance of log for chaining
     */
    public debug(...args: any[]): Log {
        return this._log(Level.debug, ...args);
    }

    /**
     * Check minimum logging level for each output channel for this log's
     * namespace, and log the message if this level is info or lower
     * @method Log#info
     * @param {any[]} ...args The arguments to log
     * @return {Log} Instance of log for chaining
     */
    public info(...args: any[]): Log {
        return this._log(Level.info, ...args);
    }

    /**
     * Check minimum logging level for each output channel for this log's
     * namespace, and log the message if this level is warn or lower
     * @method Log#warn
     * @param {any[]} ...args The arguments to log
     * @return {Log} Instance of log for chaining
     */
    public warn(...args: any[]): Log {
        return this._log(Level.warn, ...args);
    }

    /**
     * Check minimum logging level for each output channel for this log's
     * namespace, and log the message if this level isn't none
     * @method Log#error
     * @param {any[]} ...args The arguments to log
     * @return {Log} Instance of log for chaining
     */
    public error(...args: any[]): Log {
        return this._log(Level.error, ...args);
    }

    /**
     * A synonym for Log#debug
     * @method Log#log
     * @param {any[]} ...args The arguments to log
     * @return {Log} Instance of log for chaining
     */
    public log(...args: any[]): Log {
        this.debug(...args);
        return this;
    }

    /**
     * Log the error if it is set
     * @method Log#iferr
     * @param {Error|String} err The error which is checked and logged if truthy
     * @param {any[]} [...args] Additional arguments to log along with err
     * @return {Log} Instance of log for chaining
     */
    public iferr(err: any, ...args: any[]): Log {
        if(err) {
            args.push(err); // add the error to the end
            this.error(...args);
        }
        return this;
    }

    /**
     * Get the minimum logging level for the given output for this namespace.
     * If a level isn't set for the namespace, it checks its parent namespace
     * and so on until it finds one, or uses the global namespace.
     * @method Log#getLevelForOutput
     * @param {Output} output The output channel for which to get the level
     */
    public getLevelForOutput(output: Output): Level {
        let namespace: string = this.namespace;
        let config: LevelPerOutput = Log._outputPerNamespace[namespace];
        while(!(config && config[output.toString()])) {
            if(!namespace || namespace.length < 1) {
                break;
            }
            namespace = Log._parentNamespace(namespace);
            config = Log._outputPerNamespace[namespace];
        }
        return config && config[output.toString()]
            ? config[output.toString()]
            : Level.none;
    }

    // Check minimum logging level for each output channel for this log's
    // namespace, and log the message if the passed-in level is greater than or
    // equal to the minimum logging level for the output
    private _log(level: Level, ...args: any[]): Log {
        for(let output in this._outputConfig) {
            if(Log._levelGreaterOrEqual(
                level,
                this.getLevelForOutput(Output[output])
            )) {
                Log._outputHandlers[output].write(
                    this.namespace,
                    level,
                    ...args
                );
            }
        }
        return this;
    }

    // Get the minimum logging level for each output channel for this namespace
    // Note that getLevelForOutput walks up the namespace hierarchy if needed.
    private get _outputConfig(): LevelPerOutput {
        const outputConfig: LevelPerOutput = {};
        for(let output of Log._outputs) {
            const level: Level = this.getLevelForOutput(output);
            if(level && level !== Level.none) {
                outputConfig[output.toString()] = level;
            }
        }
        return outputConfig;
    }

    // Write to all outputs except console
    private _writeAllNoConsole(level: Level, ...args: any[]): void {
        for(let output in this._outputConfig) {
            if(Output[output] !== Output.console
                && Log._levelGreaterOrEqual(
                    level,
                    this.getLevelForOutput(Output[output]))
            ) {
                Log._outputHandlers[output].write(
                    this.namespace,
                    level,
                    ...args
                );
            }
        }
    }
}

export default Log;

export {OutputPerNamespace, LevelPerOutput};
